              const href = projectPath(org.slug, project.slug);
              return (
                <li key={project.id}>
                  <Link
                    href={href}
                    className={cn(
                      "flex items-center justify-between rounded px-2 py-1 text-sm",
                      isActiveSegment(pathname, href)
